-- PT111-S3-Q12. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT111-S3-Q12$batch03$ AND q.stimulus=$batch03$Despite the fact that antilock brakes are designed to make driving safer, research suggests that people who drive cars equipped with antilock brakes have more accidents than those who drive cars not equipped with antilock brakes.$batch03$ AND q.prompt=$batch03$Each of the following, if true, would help resolve the apparent discrepancy described above EXCEPT:$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT111-S3-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT111-S3-Q12$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S3-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT111-S3-Q12$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Antilock brakes are designed to make driving safer.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Drivers of cars with antilock brakes have more accidents?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Two routes. Either the brakes fail to deliver their safety in practice (malfunction, poor maintenance, misuse), or the drivers differ (more careless). Either would let the design be safe while the cars still crash more.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices give one of those routes. The answer will not explain *more* accidents.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT111-S3-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Antilock cars are driven more carelessly. The drivers, not the brakes, account for the extra accidents.$batch03$), ($batch03$B$batch03$, $batch03$Antilock brakes fail more often than regular brakes. Brakes that fail cause accidents.$batch03$), ($batch03$C$batch03$, $batch03$Without expensive maintenance, antilock brakes are worse than regular brakes. Many owners will skip that maintenance.$batch03$), ($batch03$D$batch03$, $batch03$Most drivers do not know how to use antilock brakes properly, so they do not get the safety benefit.$batch03$), ($batch03$E$batch03$, $batch03$This says where the brakes were meant to help and where the worst accidents happen. Highways affect cars with either kind of brake, and "most serious" is about severity, not number. It does not explain why antilock cars have *more* accidents.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT111-S3-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
